区间查询 query<pre><code>int query(int l,int r,int L,int R,int id){ //区间查询
    if(l&lt;=L&amp;&amp;r&gt;=R) return t[id];
    //如果当前节点区间 [L,R]⊆[l,r]（完全被查询区间包含），直接返回
    int mid=L+(R-L)/2,ans=0;
    if(l&lt;=mid) ans+=query(l,r,L,mid,lc(id));
    //如果查询区间与左儿子区间 [L,mid] 满足 [l,r]∩[L,mid]≠∅（有交集），递归左儿子并累加答案 
    if(r&gt;mid) ans+=query(l,r,mid+1,R,rc(id));
    //如果查询区间与右儿子区间 [mid+1,R] 满足 [l,r]∩[mid+1,R]≠∅（有交集），递归右儿子并累加答案 
    return ans;
    //返回答案 
}
