P3374 线段树实现.cpp<pre><code>/*
Question: 树状数组1
Source: Luogu P3374
Difficulty: Green
Date: 2026/11/7
*/
#include&lt;bits/stdc++.h&gt;
using namespace std;


#define int long long
const int N=500010;
int n,m;
int a[N],t[N&lt;&lt;2];

int lc(int x){return x&lt;&lt;1;}       // 左儿子所在 ID
int rc(int x){return x&lt;&lt;1|1;}     // 右儿子所在 ID

void build(int id,int l,int r){   // 建树 id:所在位置 l,r为范围左右端点
    if(l==r){
        t[id]=a[l];               // 叶子：直接存数组值
        return;
    }
    int mid=l+(r-l)/2;
    build(lc(id),l,mid);          // 建左子树
    build(rc(id),mid+1,r);        // 建右子树
    t[id]=t[lc(id)]+t[rc(id)];    // 合并：父 = 左 + 右
}
int query(int l,int r,int L,int R,int id){ //区间查询 l,r为查询区间的左右端点你想查 [l,r] 的和）L,R为当前结点管辖区间的左右端点 id为当前编号
    if(l&lt;=L&amp;&amp;r&gt;=R) return t[id];
    //如果当前节点区间 [L,R]⊆[l,r]（完全被查询区间包含），直接返回
    int mid=L+(R-L)/2,ans=0;
    if(l&lt;=mid) ans+=query(l,r,L,mid,lc(id));
    //如果查询区间与左儿子区间 [L,mid] 满足 [l,r]∩[L,mid]≠∅（有交集），递归左儿子并累加答案
    if(r&gt;mid) ans+=query(l,r,mid+1,R,rc(id));
    //如果查询区间与右儿子区间 [mid+1,R] 满足 [l,r]∩[mid+1,R]≠∅（有交集），递归右儿子并累加答案
    return ans;
    //返回答案
}
void add(int l,int k,int L,int R,int id){ //k为要加的值 l为要修改的位置（把 a[l] 加上 k）L,R为当前结点管辖区间 id为当前编号
    if(L==R){
        t[id]+=k;
        return;
    }
    int mid=L+(R-L)/2;
    if(l&lt;=mid)  add(l,k,L,mid,lc(id)); //修改点 l∈[L,mid]（在左儿子区间内）
    else add(l,k,mid+1,R,rc(id));     //否则修改点 l∈[mid+1,R]（在右儿子区间内）
    t[id]=t[lc(id)]+t[rc(id)];        //更新自己
    return;
}

signed main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin&gt;&gt;n&gt;&gt;m;
    for(int i=1;i&lt;=n;i++) cin&gt;&gt;a[i];
    build(1,1,n);
    while(m--){
        int op;
        cin&gt;&gt;op;
        if(op==1){
            int x,k;
            cin&gt;&gt;x&gt;&gt;k;
            add(x,k,1,n,1);
        }
        else if(op==2){
            int x,y;
            cin&gt;&gt;x&gt;&gt;y;
            cout&lt;&lt;query(x,y,1,n,1)&lt;&lt;endl;
        }
    }
    return 0;
}
